// === Tab: mySketch ===
// Every Year a Whisper
// For the #WCCChallenge «Growth» (join the discord! https://discord.gg/S8c7qcjw2b)

// This sketch explores tree rings, which are the result of the slow growth of the tree and the story they tell.
// Used Gorilla Sun's tutorial as base https://www.gorillasun.de/blog/radial-perlin-noise-and-generative-tree-rings/,
// then added some few more variation and features.
//
// Click or press space to generate a new image.

let maxRadius
let minRadius = 30
let minRingSpacing = 3
let maxRingSpacing = 15

let scale = 50
let resolution = 0.002

let dAngle
let dRadius

let palettes = [
  // Earthy palettes
  ["#abc4ab","#a39171","#dcc9b6","#727d71","#6d4c3d"],
  ["#f0ead2","#dde5b6","#adc178","#a98467","#6c584c"],
  ["#774936","#6e4230","#653a2a","#5c3324","#532c1e","#4a2419","#411d13","#38160d","#2f0e07","#260701"],
  ["#231c07","#392a16","#634133","#b86f52","#eda268"],
  ["#9b8816","#f98948","#5d3a00","#684e32","#f9ea9a"],
  ["#558a78","#853512","#eeaa23","#614433","#4a834c"],
  // Standard palettes
  ["#ed225d", "#3caf65", "#0d40bf", "#f5b800", "#2a2a2a"],
  ["#b30000", "#e6cf00", "#1283b3", "#fafafa", "#0a0a0a"],
  ["#606c38", "#283618", "#fefae0", "#dda15e", "#bc6c25"],
  ["#001427", "#708d81", "#f4d58d", "#bf0603", "#8d0801"],
  ["#3d5a80", "#98c1d9", "#e0fbfc", "#ee6c4d", "#293241"],
  ["#4464a1", "#62b6de", "#b3dce0", "#fafafa", "#ffc5c7", "#ee726b", "#cd1440"],
  ["#353535", "#3c6e71", "#ffffff", "#d9d9d9", "#284b63"],
  ["#0081a7", "#00afb9", "#fdfcdc", "#fed9b7", "#f07167"],
  ["#004b23", "#006400", "#007200", "#008000", "#38b000", "#70e000", "#9ef01a", "#ccff33"],
  ["#0a1128", "#001f54", "#034078", "#1282a2", "#fefcfb"],
  ["#2d3142", "#bfc0c0", "#ffffff", "#ef8354", "#4f5d75"],
  ["#04151f", "#183a37", "#efd6ac", "#c44900", "#432534"],
  ["#ca9ce1", "#54defd", "#f1ffc4", "#ffcaaf", "#28587b"],

]
let palette
let minOffset, maxOffset
let radialLineDensity = 0.3 // Probability of drawing circles along the line
let splitAngles = []
let mainCanvas, bufferCanvas

function setup() {
  mainCanvas = createCanvas(windowWidth, windowHeight)
  bufferCanvas = createGraphics(windowWidth, windowHeight)
  initialize()
}

function initialize() {
  clear()
  maxRadius = (max(windowWidth, windowHeight) / 2) * random(1.2, 1.5)
  minRadius = random(10, 30)
  dAngle = random(TAU)
  dRadius = random(maxRadius / 5, maxRadius / 2)
  palette = random(palettes)
  minOffset = random(10, 50)
  maxOffset = random(100, 200)
  let numSplits = random(8, 20)
  splitAngles = []
  for (let i = 0; i < numSplits; i++) {
    splitAngles.push(random(TAU))
  }
}

function draw() {
  push()
  translate(-dRadius * cos(dAngle) / 2, -dRadius * sin(dAngle) / 2)
  // Translate so the center is in one of the 4 corners of the 3x3 grid central square (composition rule)
  let compX = width / 3 * random([1, 2])
  let compY = height / 3 * random([1, 2])
  translate(compX, compY)

  // Start from maxRadius and work inward
  let currentRadius = maxRadius

  let _wG_1 = 0; while ((currentRadius > 0) && ++_wG_1 < 20000) {
    numPoints = map(noise(currentRadius * resolution), 0, 1, 50, 800)

    let dr = map(currentRadius, 0, maxRadius, 0, dRadius)
    let dx = dr * cos(dAngle)
    let dy = dr * sin(dAngle)

    push()
    translate(dx, dy)
    strokeWeight(map(currentRadius, 0, maxRadius, 0.5, 5))
    stroke(random(palette))
    fill(random(palette))
    if (currentRadius < minRadius) {
      noFill()
    }

    // Create a dash pattern with random intervals
    let numDashes = 2 * random(20, 50)
    let dashPattern = []
    for (let i = 0; i < numDashes; i++) {
      dashPattern.push(random(2, 10))
    }
    drawingContext.lineCap = random() < 0.7 ? "round" : "square"
    if (random() < 0.5 && currentRadius < maxRadius * 0.9) {
      drawingContext.setLineDash(dashPattern)
    } else {
      drawingContext.setLineDash([])
    }
    // If it's the outer ring, make it thicker, darker, and add a shadow
    if (currentRadius === maxRadius) {
      strokeWeight(random(50, 100))
      let c = random(palette)
      c = chroma(c).darken(random(1, 2)).saturate(random(0.5, 2)).hex()
      stroke(c)
      fill(c)
      drawingContext.shadowColor = 'black'
      drawingContext.shadowBlur = random(50, 100)
      drawingContext.shadowOffsetX = random(-10, 10)
      drawingContext.shadowOffsetY = random(-10, 10)
    } else if (random() < 0.2) {
      // Add a small shadow, follow the dAngle for the direction
      let shadowX = random(5, 10) * cos(dAngle)
      let shadowY = random(5, 10) * sin(dAngle)
      drawingContext.shadowColor = 'black'
      drawingContext.shadowBlur = random(20, 50)
      drawingContext.shadowOffsetX = shadowX
      drawingContext.shadowOffsetY = shadowY
    }
    beginShape()
    for (a = 0; a < TAU; a += (Math.max(0.001, Math.abs(TAU / numPoints)) || 1)) {
      curveVertex(...getRingPoint(a, currentRadius))
    }
    endShape(CLOSE)

    // Calculate next radius with variable spacing based on current radius
    let radiusVariation = map(currentRadius, 0, maxRadius, 0.1, 0.8) // More variation for larger radii
    let baseSpacing = map(currentRadius, 0, maxRadius, minRingSpacing, maxRingSpacing)
    let spacing = baseSpacing + random(-baseSpacing * radiusVariation, baseSpacing * radiusVariation)
    spacing = max(spacing, 2) // Ensure minimum spacing

    currentRadius -= spacing
    pop()
  }
  drawRadialLines()

  pop()
  granulate(floor(random(10, 40)))
  // Save the image to a buffer, then put the background behind it (need to do this later for the granulate and the shadow)
  push()
  bufferCanvas.clear()
  bufferCanvas.image(mainCanvas, 0, 0)
  clear()
  let bgColor = random(palette)
  let c1 = chroma(bgColor).brighten(random(0.5, 1)).desaturate(random(0.5, 2)).hex()
  background(c1)
  let c2 = chroma(bgColor).darken(random(0.5, 1)).saturate(random(0.5, 2)).alpha(window.color(random(0.5, 1))).hex()
  // Draw a frame
  stroke(c2)
  strokeWeight(random(5, 20))
  if (random() < 0.5) {
    drawingContext.setLineDash([random(20, 40), random(20, 40)])
    drawingContext.lineCap = 'square'
  }
  noFill()
  rectMode(CENTER)
  rect(width / 2, height / 2, width * 0.9, height * 0.9)
  image(bufferCanvas, 0, 0)
  pop()

  noLoop()
}

function getRingPoint(angle, radius) {

  // If the angle is within 1 degree of a split angle, return the point of a smaller radius
  for (let splitAngle of splitAngles) {
    if (abs(angle - splitAngle) < radians(1)) {
      radius = radius * random(0.985, 0.995)
    }
  }

  let x = radius * cos(angle)
  let y = radius * sin(angle)
  let n = map(noise(x * resolution, y * resolution), 0, 1, -scale, scale)
  let offsetX = map(noise(x * resolution, y * resolution), 0, 1, minOffset, maxOffset)
  let offsetY = map(noise(x * resolution, y * resolution), 0, 1, minOffset, maxOffset)
  return [x + n + offsetX, y + n + offsetY]
}

function drawRadialLines() {
  let radialLines = []
  // Calculate the delta we applied at maxRadius and substract it
  let deltaX = dRadius * cos(dAngle)
  let deltaY = dRadius * sin(dAngle)

  push()
  let centerPoint = getRingPoint(0, 0)

  for (let radialAngle of splitAngles) {
    let ringPoint = getRingPoint(radialAngle, maxRadius * random(0.8, 0.95))
    let offsetX = random(-10, 10)
    let offsetY = random(-10, 10)
    stroke('white')
    strokeWeight(5)
    dottedLine(centerPoint[0] + offsetX, centerPoint[1] + offsetY, ringPoint[0] + deltaX, ringPoint[1] + deltaY)

  }
  pop()
}

function dottedLine(x0, y0, x1, y1) {
  let maxDistance = dist(0, 0, x1, y1)
  // Divide the line so there's roughly 1 point every N pixels
  let delta = 2 / maxDistance
  let opacity = random(100, 150)
  let c = color(random(palette))
  c.setAlpha(opacity)
  stroke(c)
  let d = 0
  let _wG_2 = 0; while ((d < 1) && ++_wG_2 < 20000) {
    let p = 0.2 + (1 - d) / 2
    if (random() < p) {
      let x = lerp(x0, x1, d) + random(-5, 5)
      let y = lerp(y0, y1, d) + random(-5, 5)
      strokeWeight(random(0.5, 5))
      point(x, y)
    }
    d += random(delta * 0.8, delta * 1.2)
  }

}

function granulate(amount) {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    // Skip if the pixel is transparent
    if (pixels[i + 3] === 0) {
      continue
    }
    const grainAmount = random(-amount, amount);
    pixels[i] += grainAmount;
    pixels[i + 1] += grainAmount;
    pixels[i + 2] += grainAmount;
  }
  updatePixels();
}

function keyPressed() {
  if (key === ' ') {
    initialize()
    redraw()
  }
}

function mouseClicked() {
  initialize()
  redraw()
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
        Triangulate: function() { return []; },
        getArea: function() { return 0; }
    };
}
if (typeof window.P5Capture === 'undefined') {
    window.P5Capture = {
        getInstance: function() {
            return { start: function() {}, stop: function() {}, setFormat: function() {} };
        },
        setDefaultOptions: function() {}
    };
}

// 1.9 免疫 OPC (OpenProcessing Controller) 與 WebGL 內部 setUniform 崩潰
if (typeof window.OPC === 'undefined') {
    window.OPC = {
        title: function() {},
        slider: function() {},
        button: function() {},
        toggle: function() {},
        color: function() {}
    };
}
if (typeof p5 !== 'undefined' && p5.Shader) {
    const origSetUniform = p5.Shader.prototype.setUniform;
    p5.Shader.prototype.setUniform = function(name, val) {
        if (!this) return this;
        try {
            return origSetUniform.call(this, name, val);
        } catch(e) {
            return this;
        }
    };
}

// 1.95 免疫某些特定遊戲模組對 parent / maeExportApis_ 或是唯讀屬性的寫入崩潰
try {
  if (typeof window.parent !== 'undefined') {
    if (!window.parent.maeExportApis_) {
      try {
        window.parent.maeExportApis_ = function() {};
      } catch(e) {}
    }
  }
} catch(e) {}

// 1.96 免疫 textmode 缺失以及 loadSVG / p5.SVG 插件型別拋錯
if (typeof textmode === 'undefined') { window.textmode = function() {}; }
if (typeof MAT === 'undefined') { window.MAT = []; }
if (typeof SIDES === 'undefined') { window.SIDES = 4; }
if (typeof GRIDBOX === 'undefined') { window.GRIDBOX = 10; }
if (typeof COLUMNS === 'undefined') { window.COLUMNS = 5; }
if (typeof tileSize === 'undefined') { window.tileSize = 30; }
if (typeof mouseTileX === 'undefined') { window.mouseTileX = 0; }
if (typeof p5 !== 'undefined') {
  if (!p5.prototype.loadSVG) {
    p5.prototype.loadSVG = function(path, success, failure) {
      if (success) success({});
      return {};
    };
  }
  // 免疫 window.VERSION 唯讀寫入錯誤
  try {
    Object.defineProperty(window, 'VERSION', {
      value: "p5-stub",
      writable: true,
      configurable: true
    });
  } catch(e) {}
}

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || path.startsWith('http') || (path.startsWith('data:') === false && path.indexOf('.') === -1)) {
            // 當發現是遠端 URL、相對路徑或格式無副檔名時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖與 CORS 錯誤
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };

    // 修正 img.loadPixels / img.resize 缺失與未非同步載入完成呼叫
    if (!p5.Image.prototype.loadPixels) { p5.Image.prototype.loadPixels = function() { return this; }; }
    if (!p5.Image.prototype.resize) { p5.Image.prototype.resize = function() { return this; }; }
    if (!p5.Image.prototype.get) { p5.Image.prototype.get = function() { return [0,0,0,255]; }; }
    if (!p5.Image.prototype.width) {
        Object.defineProperty(p5.Image.prototype, 'width', {
            get: function() { return this._width || 1280; },
            set: function(v) { this._width = v; }
        });
    }
    if (!p5.Image.prototype.height) {
        Object.defineProperty(p5.Image.prototype, 'height', {
            get: function() { return this._height || 720; },
            set: function(v) { this._height = v; }
        });
    }

    // 修正 p5.Graphics / p5.Renderer / Element.prototype.style
    if (p5.Graphics && p5.Graphics.prototype) {
        if (!p5.Graphics.prototype.loadPixels) { p5.Graphics.prototype.loadPixels = function() { return this; }; }
    }
}

// 2.2 修正 p5.Table / loadTable / getRowCount 缺失與錯誤
if (typeof p5 !== 'undefined' && p5.Table) {
    if (!p5.Table.prototype.getRowCount) { p5.Table.prototype.getRowCount = function() { return 0; }; }
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (!this || this.width === 0 || this.height === 0) {
            return [0,0,0,255];
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return [0,0,0,255];
        }
    };
}

